# 입력 계산기
a = float(input('첫 번째 수: '))
b = float(input('두 번째 수: '))
op = input('연산 (+,-,*,/): ').strip()
if op == '+':
    print(a + b)
elif op == '-':
    print(a - b)
elif op == '*':
    print(a * b)
elif op == '/':
    print(a / b)
else:
    print('모르는 연산자')

# 계산기 + 0 나누기 처리
def calc(x: float, y: float, op: str):
    if op == '+':
        return x + y
    if op == '-':
        return x - y
    if op == '*':
        return x * y
    if op == '/':
        if y == 0:
            raise ZeroDivisionError('0으로 나눌 수 없음')
        return x / y
    raise ValueError('연산자 오류')

if __name__ == '__main__':
    a = float(input('첫 번째 수: '))
    b = float(input('두 번째 수: '))
    op = input('연산: ').strip()
    try:
        print('결과', calc(a, b, op))
    except (ValueError, ZeroDivisionError) as e:
        print('에러', e)

